const std = @import("std");

pub fn toDecimal(input: []const u8) !u64 {
    var value: u64 = 0;
    for (input) |raw| {
        const c = if (2 == 16) std.ascii.toLower(raw) else raw;
        const digit: u64 = if (c >= '0' and c <= '9') c-'0' else if (c >= 'a' and c <= 'f') c-'a'+10 else return error.InvalidDigit;
        if (digit >= 2) return error.InvalidDigit;
        const mul = @mulWithOverflow(value, 2);
        const sum = @addWithOverflow(mul[0],digit);
        if (mul[1] != 0 or sum[1] != 0) return error.Overflow;
        value = sum[0];
    }
    return value;
}

tests.test_binary.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("binary.zig");

test "valid numbers, leading zeros and invalid input" {
    try t.expectEqual(@as(u64,0),try m.toDecimal("0"));
    try t.expectEqual(@as(u64,1),try m.toDecimal("0001"));
    try t.expectEqual(@as(u64,43),try m.toDecimal("101011"));
    try t.expectError(error.InvalidDigit,m.toDecimal("12z"));
    try t.expectError(error.InvalidDigit,m.toDecimal("-1"));
    try t.expectError(error.InvalidDigit,m.toDecimal(" 1"));
    try t.expectError(error.InvalidDigit,m.toDecimal("A"));
    try t.expectError(error.Overflow,m.toDecimal("11111111111111111111111111111111111111111111111111111111111111111"));
}
